def prove_autocomplete_comuni():
    """La tendina dei comuni deve saper cercare il formato che
    PROPONE (ago 2026, caso dal campo su «Gubbio»): cercava sul solo
    nome, quindi «Gubbio (PG)» — il valore che lei stessa mette nel
    campo, e che finisce in colonna — non trovava piu' niente, e chi
    tornava a ritoccare la zona lo leggeva come «il mio comune non
    c'e'».
    Si fa GIRARE l'endpoint vero: una sentinella direbbe che il ramo
    esiste, mai che nella risposta ci sia Gubbio."""
    print("\n[autocomplete dei comuni]")
    import csv
    import re
    import unicodedata

    amb = {"re": re, "unicodedata": unicodedata, "csv": csv, "os": os,
           "COMUNI": {}, "COMUNI_LISTA": [], "_COMUNI_PREFISSO": None,
           # l'endpoint non deve poter chiedere chi sei: qui la
           # guardia e' uno stub, e che ci sia DAVVERO lo dice la
           # sentinella in fondo
           "verifica_utente": lambda *a, **k: None,
           "Header": lambda d="": d, "Cookie": lambda d="": d}
    i = _SORGENTE.index("PREPOSIZIONI_COMUNI = {")
    exec(_SORGENTE[i:_SORGENTE.index("}", i) + 1], amb)
    for f in ("normalizza", "carica_comuni", "_comuni_prefisso",
              "cerca_comuni"):
        exec(pezzo(f), amb)
    amb["carica_comuni"]()
    prova("il dataset comuni si carica", True,
          len(amb["COMUNI_LISTA"]) > 7000)

    def cerca(q):
        return [c["nome"] for c in amb["cerca_comuni"](q)["comuni"]]

    # il caso dal campo, nelle due forme: quella che si digita e
    # quella che la tendina scrive da se'
    prova("«gub» propone Gubbio", ["Gubbio"], cerca("gub"))
    prova("«Gubbio (PG)» propone Gubbio", ["Gubbio"],
          cerca("Gubbio (PG)"))
    prova("...e «Gubbio (P» a mezza sigla", ["Gubbio"],
          cerca("Gubbio (P"))
    prova("...e la forma senza parentesi", ["Gubbio"],
          cerca("gubbio pg"))
    # la sigla non apre una seconda strada: non si cerca PER sigla,
    # o «PG» tirerebbe fuori i 59 comuni di una provincia che
    # nessuno sta scrivendo
    prova("la sola sigla non propone nulla", [], cerca("PG"))
    # e gli omonimi restano distinguibili, che e' il motivo per cui
    # la tendina propone la sigla
    prova("«castro bg» arriva a un solo Castro", 1,
          len(cerca("castro bg")))
    prova("«castro» li propone tutti", True, len(cerca("castro")) > 1)
    # le regressioni della tendina di sempre
    prova("un carattere solo tace", [], cerca("g"))
    prova("il tetto resta 10", 10, len(cerca("ca")))
    prova("nome composto con lo spazio", True,
          "Gualdo Tadino" in cerca("gualdo ta"))
    prova("accenti e maiuscole indifferenti", True,
          "Gualtieri Sicaminò" in cerca("GUALTIERI SICAMINO"))
    prova("un prefisso che non esiste tace", [], cerca("zzq"))
    # LA TERZA CHIAVE (ago 2026, il giro dopo): «reggio emilia» e
    # «cassano ionio» sono zone VALIDE — carica_comuni ne registra
    # l'alias senza preposizioni apposta — e restavano senza
    # suggerimento. Chi le digita ottiene il nome UFFICIALE.
    prova("l'alias senza preposizioni propone il nome vero",
          ["Reggio nell'Emilia"], cerca("reggio emilia"))
    prova("...anche a meta' («reggio em»)", ["Reggio nell'Emilia"],
          cerca("reggio em"))
    prova("...e l'altro caso di casa («cassano ionio»)",
          ["Cassano all'Ionio"], cerca("cassano ionio"))
    # la zona che l'alias fa riconoscere e il nome che si propone
    # devono essere lo STESSO comune, o si suggerirebbe una forma
    # che il campo poi non accetta
    prova("l'alias e la zona parlano dello stesso comune", True,
          amb["normalizza"]("Reggio nell'Emilia") in amb["COMUNI"])
    # e una voce non si propone due volte perche' ha tre chiavi
    prova("nessun doppione con tre chiavi", True,
          all(len(set(cerca(p))) == len(cerca(p))
              for p in ("reggio", "san", "castel", "ca")))
    # L'alias non allarga la ricerca a caso: resta un PREFISSO.
    # «emilia» sta DENTRO l'alias «reggio emilia» ma non in testa,
    # quindi e' il caso che distingue startswith da una ricerca a
    # pezzi — con «in» al suo posto qui uscirebbe Reggio. (Il primo
    # caso scritto, «emilia reggio», non poteva fallire: non e'
    # sottostringa di niente, e restava vuoto comunque.)
    prova("il prefisso resta un prefisso, non una sottostringa", [],
          cerca("emilia"))

    # La chiave composta e' quella di carica_comuni e non una
    # seconda ricetta: se divergessero, la tendina proporrebbe una
    # forma che la zona poi non riconosce (o il contrario), e non se
    # ne accorgerebbe nessuno.
    nz = amb["normalizza"]
    prova("la forma composta e' una chiave viva del dizionario", True,
          all(nz(f"{c['nome']} {c['provincia']}") in amb["COMUNI"]
              for c in amb["COMUNI_LISTA"]))
    corpo = codice(pezzo("cerca_comuni"))
    prova("l'endpoint resta autenticato", True,
          "verifica_utente(" in corpo)
    prova("...e non normalizza piu' 7.900 nomi per battuta", 1,
          corpo.count("normalizza("))


# ====================================================================
def prove_testo_evento():
    """Il testo di un evento e' il cuore CONDIVISO fra chi scrive
    l'annuncio e chi decide se la moderazione l'ha gia' giudicato: se
    i due divergessero, un annuncio fermo sembrerebbe cambiare a ogni
    giro e si ripagherebbe l'AI per nulla."""
    print("\n[testo dell'evento]")
    import importa_nostr as imp

    nip99 = {"kind": 30402, "content": "Come nuova, spedisco",
             "tags": [["title", " Tastiera "], ["summary", "riassunto"]]}
    prova("NIP-99: titolo dal tag, ripulito", "Tastiera",
          imp.testo_evento(nip99)[0])
    prova("NIP-99: il content batte il summary", "Come nuova, spedisco",
          imp.testo_evento(nip99)[1])
    prova("NIP-99: senza content vale il summary", "riassunto",
          imp.testo_evento({"kind": 30402, "content": "",
                            "tags": [["title", "x"],
                                     ["summary", "riassunto"]]})[1])
    # Il caso che l'estrazione fatta a mano nel vaglio sbagliava: per
    # un prodotto NIP-15 il titolo sta nel JSON, non nei tag — e un
    # titolo vuoto vuol dire moderare un annuncio senza leggerlo.
    prova("NIP-15: il titolo si pesca dentro il JSON", "Miele",
          imp.testo_evento({"kind": 30018, "tags": [],
                            "content": '{"name":"Miele","description":"buono"}'})[0])
    prova("NIP-15: JSON storto non esplode", ("", ""),
          imp.testo_evento({"kind": 30018, "tags": [], "content": "{{{"}))
    prova("descrizione vuota diventa il trattino", "—",
          imp.testo_evento({"kind": 30402, "content": "",
                            "tags": [["title", "x"]]})[1])
    # I troncamenti sono quelli con cui l'annuncio finisce nel
    # database: se qui fossero piu' larghi, il confronto direbbe
    # «cambiato» per sempre su ogni testo lungo.
    lungo = {"kind": 30402, "content": "d" * 2000,
             "tags": [["title", "t" * 200]]}
    prova("titolo troncato a 120", 120, len(imp.testo_evento(lungo)[0]))
    prova("descrizione troncata a 1500", 1500, len(imp.testo_evento(lungo)[1]))


