def prove_tag_client():
    """La firma di Barattolo sugli eventi Nostr (ago 2026): il tag
    `client` NIP-89 sta su OGNI evento 30402 che componiamo noi,
    chiunque lo firmi — piattaforma, BIVIO (che eredita i tags di
    evento_annuncio), modifica firmata degli importati. E' cio' che le
    classifiche dei marketplace (Nostrology) leggono, e leggono la
    sola POSIZIONE 1: il nome. Le eseguibili valgono piu' delle
    sentinelle, perche' un tag che manca non fallisce da solo: si
    sparisce dalla classifica, in silenzio."""
    print("\n[il tag client di Barattolo]")
    import importa_nostr as imp
    import inspect
    import json as _json

    amb = {"json": _json, "URL_PUBBLICO": "https://barattolo.store",
           "LINK_BOT": "https://t.me/ilbarattolobot",
           "CONDIZIONI": {},
           # tag_client legge _NOSTR alla CHIAMATA: la chiave finta
           # accende la forma piena, l'azzeramento (sotto) il ripiego
           "_NOSTR": (None, "f" * 64),
           "RELAYS_VERIFICA": ("wss://relay.damus.io",),
           # la firma vera non serve alla prova: si guarda l'evento
           "firma_evento": lambda kind, tags, content: {
               "kind": kind, "tags": tags, "content": content}}
    i = _SORGENTE.index("CATEGORIE_SENZA_CONDIZIONE = frozenset(")
    exec(_SORGENTE[i:_SORGENTE.index("\n\n", i)], amb)
    for f in ("senza_condizione", "condizione_da_mostrare",
              "_foto_url_nostr"):
        exec(pezzo(f), amb)
    i = _SORGENTE.index("CONDIZIONE_NIP99 = {")
    exec(_SORGENTE[i:_SORGENTE.index(
        "\n\n\n", _SORGENTE.index("def tag_commercio"))], amb)
    exec(pezzo("evento_annuncio"), amb)
    exec(pezzo("evento_annuncio_importato"), amb)

    atteso = ["client", "Barattolo",
              "31990:" + "f" * 64 + ":barattolo", "wss://relay.damus.io"]
    riga = {"id": 42, "titolo": "Lampada", "descrizione": "Bella",
            "prezzo_sats": 1000, "creato": 111, "categoria": "",
            "zona": "", "consegna": "", "condizione": "", "quantita": 1,
            "anche_digitale": 0, "valuta": "sats", "foto": "[]"}
    ev = amb["evento_annuncio"](dict(riga), "active")
    prova("l'evento firmato da noi porta il tag pieno", True,
          atteso in ev["tags"])
    imp_riga = {"nostr_origine_d": "d1", "nostr_origine_foto": "[]",
                "foto": "[]", "categoria": "", "consegna": "",
                "spedizione_sats": 0, "spedizione_eur": 0.0,
                "condizione": "", "quantita": 1, "anche_digitale": 0,
                "valuta": "sats"}
    ev2 = amb["evento_annuncio_importato"](imp_riga, "T", "D", "", "",
                                           "sats", 1000, 0.0, 111)
    prova("anche l'evento della modifica firmata lo porta", True,
          atteso in ev2["tags"])
    prova("...e l'import lo IGNORA: il giro non si sporca", {},
          imp.estrai_commercio(ev2))
    amb["_NOSTR"] = None
    prova("senza chiave resta il nome nudo, la posizione che conta",
          ["client", "Barattolo"], amb["tag_client"]())

    # Il nome e' l'identita' in classifica (raggruppamento per stringa
    # ESATTA: «BTCPayServer-Shopstr» e' una voce separata da «Shopstr»)
    prova("il nome in classifica e' congelato", True,
          'NOME_CLIENT_NOSTR = "Barattolo"' in _SORGENTE)
    # IL CENSIMENTO della regola: chi compone un 30402 da zero deve
    # portare il tag. Il terzo compositore di domani fa rossa la prima
    # riga, e la seconda pretende che porti anche lui il suo append.
    # (firme_nostr_da_fare non c'e': riavvolge base["tags"] di
    # evento_annuncio — lo sorveglia gia' prove_firme_nostr.)
    siti = (_SORGENTE.count("firma_evento(30402") +
            _SORGENTE.count('"kind": 30402'))
    prova("i posti che compongono un 30402 da zero sono due", 2, siti)
    prova("...e ognuno porta il suo tag", 2,
          _SORGENTE.count("tags.append(tag_client())"))
    prova("tag_commercio resta pulito: e' la lista che l'import rilegge",
          False, "tag_client" in pezzo("tag_commercio"))
    prova("estrai_commercio non legge mai il tag client", False,
          '"client"' in inspect.getsource(imp.estrai_commercio))

    # Lo script della ripubblicazione una-tantum
    src = open("ripubblica_tag_client.py", encoding="utf-8").read()
    # L'ancora e' la CODA della SELECT vera, non la parola: la stessa
    # condizione vive anche nella docstring dello script, e la prima
    # stesura di questa sentinella restava verde con la WHERE mutilata
    # (l'ha detto la tortura, M5 — la prova che legge la prosa).
    prova("lo script rifirma solo i NOSTRI, mai gli eventi altrui", True,
          "AND nostr_autore='' ORDER BY id" in src
          and "contatto_nostr=''" in src)
    prova("...zero copie della fabbrica: riusa server.evento_annuncio",
          True, "server.evento_annuncio(" in src
          and "def evento_annuncio" not in src)
    prova("...la testa si scrive solo dopo un relay OK", True,
          src.index("if ok:") < src.index(
              "UPDATE annunci SET nostr_event_id"))
    prova("...anteprima di serie", True, "if not scrivi:" in src)
    prova("...l'handler 31990 con la sua d", True,
          '["d", "barattolo"]' in src and '["k", "30402"]' in src)


# ====================================================================
def prove_anello():
    """Il tappo del bug dell'anello (lug 2026): Barattolo non importa
    Barattolo, e l'import non crede sulla parola al filtro `authors`
    del relay. Sono due righe che un rifattorizzatore distratto
    toglierebbe senza accorgersi, e costano 40 annunci fantasma."""
    print("\n[l'anello non si richiude]")
    import re
    amb = {"npub_to_hex": None}
    # npub_to_hex serve al confronto npub↔hex: si estrae con lui
    for f in ("npub_to_hex", "chiave_di_casa"):
        exec(pezzo(f), amb)
    nostra = "ab" * 32
    amb["_NOSTR"] = (None, nostra)
    di_casa = amb["chiave_di_casa"]
    prova("la nostra hex è di casa", True, di_casa(nostra))
    prova("in maiuscolo lo è lo stesso", True, di_casa(nostra.upper()))
    prova("quella di un altro no", False, di_casa("cd" * 32))
    prova("il vuoto non è di casa", False, di_casa(""))
    prova("una stringa storta non esplode", False, di_casa("npub1zzz"))
    # anche in forma npub, che è come la scrive utenti.npub_accesso
    i = _SORGENTE.index("CHARSET_BECH32 = ")
    exec(_SORGENTE[i:_SORGENTE.index("\n", i)], amb)
    exec(pezzo("_bech32_polymod"), amb)
    exec(pezzo("hex_to_npub"), amb)
    prova("la nostra npub è di casa", True,
          di_casa(amb["hex_to_npub"](nostra)))
    prova("la npub di un altro no", False,
          di_casa(amb["hex_to_npub"]("cd" * 32)))
    # a Nostr spento non deve dire di sì a tutto
    amb["_NOSTR"] = None
    prova("con Nostr spento nessuna chiave è «di casa»", False,
          di_casa(nostra))

    # La sentinella sull'autore: qui non c'è una funzione da chiamare
    # (il filtro è dentro importa_venditore), quindi si guarda che ci
    # sia. Grezza, ma è esattamente il pezzo che sparisce per sbaglio.
    sorgente_imp = open("importa_nostr.py", encoding="utf-8").read()

    def pezzo_imp(nome):
        """pezzo(), ma sull'altro file: `pezzo` legge solo server.py."""
        i = sorgente_imp.index(f"def {nome}(")
        return sorgente_imp[i:sorgente_imp.index("\n\n\n", i)]

    i = sorgente_imp.index("def importa_venditore(")
    corpo = sorgente_imp[i:sorgente_imp.index("\ndef ", i + 10)]
    prova("l'import confronta l'autore dell'evento con la chiave chiesta",
          True,
          bool(re.search(r'\(e\.get\("pubkey"\)\s*or\s*""\)\.lower\(\)\s*'
                         r'[!=]=\s*hexkey', corpo)))

    # --- Il riflesso non e' una fonte (ago 2026) --------------------
    # Il gemello di chiave_di_casa un piano piu' in basso: un evento
    # che abbiamo composto NOI e fatto firmare al venditore e' lo
    # specchio di una riga nata qui, e importarlo «adottava» quella
    # riga (via il match per TITOLO), togliendo al venditore la
    # modifica dal form e consegnando a una sua NIP-09 il potere di
    # spegnerla su Barattolo.
    amb2 = {}
    exec(pezzo_imp("id_riflesso"), amb2)
    exec(pezzo_imp("e_riflesso"), amb2)
    idr, erifl = amb2["id_riflesso"], amb2["e_riflesso"]
    # 1ª condizione: la coordinata e' una NOSTRA
    prova("«barattolo-42» nomina la riga 42", 42, idr("barattolo-42"))
    prova("una coordinata di un altro non nomina niente", 0,
          idr("mio-annuncio-42"))
    # ...nemmeno una lunga uguale, che senza il prefisso finirebbe per
    # nominare la riga 89 di un altro mercatino (torturato: togliendo
    # il controllo del prefisso, questa riga diventa rossa e le altre
    # no — era l'unico buco della mutazione)
    prova("...nemmeno una che ha le cifre al posto giusto", 0,
          idr("altrosito-89"))
    prova("il vuoto non nomina niente", 0, idr(""))
    prova("«barattolo-» senza numero non nomina niente", 0,
          idr("barattolo-"))
    prova("un id non numerico non nomina niente", 0, idr("barattolo-89x"))
    # 2ª e 3ª: la riga e' NATIVA ed e' firmata proprio da quella chiave
    mia = "bb" * 32
    prova("riga nativa firmata da lui: e' un riflesso", True,
          erifl(("", mia), mia))
    prova("...anche se la colonna e' in maiuscolo", True,
          erifl(("", mia.upper()), mia))
    prova("riga IMPORTATA: non e' un riflesso (l'import e' a casa sua)",
          False, erifl(("npub1qualcosa", mia), mia))
    prova("riga mai firmata: non e' un riflesso", False, erifl(("", ""), mia))
    prova("due vuoti non sono una prova", False, erifl(("", ""), ""))
    prova("firmata da un ALTRO: non e' un riflesso", False,
          erifl(("", "cc" * 32), mia))
    prova("riga sparita: non e' un riflesso", False, erifl(None, mia))
    # E che il filtro sia ancora attaccato al giro d'import: sono tre
    # righe che un riordino porta via senza rompere nessun'altra prova.
    prova("l'import chiama i due giudici del riflesso", True,
          "id_riflesso(" in corpo and "e_riflesso(" in corpo)
    # find() e non index(): se la chiamata sparisce questa prova deve
    # FALLIRE, non esplodere — una prova che si schianta fa rossa la CI
    # senza dire quale patto e' saltato.
    dove = corpo.find("e_riflesso(")
    prova("...e li chiama PRIMA del vaglio (l'AI non giudica i nostri)",
          True, 0 <= dove < corpo.index("if vaglio:"))

    # --- LE DUE TESTE (ago 2026, dal campo: gli annunci 208 e 209) ---
    # Il terzo membro della famiglia. L'anello importava NOI; il
    # riflesso importava lo specchio di una riga nata qui; questo si
    # prende una riga nativa QUALUNQUE, per via del match per TITOLO —
    # che fra i candidati accetta `venditore_id=?` — e le lascia
    # addosso la sua testa, perche' l'UPDATE scrive `contatto_nostr` e
    # `nostr_event_id` non lo nomina proprio. Una riga con tutt'e due
    # dice due cose incompatibili, e il venditore perde Modifica,
    # rifornimento e perfino «ritira il doppione».
    import asyncio
    import sqlite3

    def sql_di(blocco, param="(a["):
        """La query dentro un `con.execute(...)`: i pezzi di stringa
        fino ai parametri, che cominciano sempre con `(a[` (o con quel
        che dice `param`: il ramo «sold» passa `(tt[`). Se non la
        ritrova torna '' e la prova FALLISCE invece di esplodere — una
        prova che si schianta fa rossa la CI senza dire quale patto e'
        saltato (la lezione del find() al posto dell'index())."""
        i = blocco.find("con.execute(")
        j = blocco.find(param, i + 1)
        if i < 0 or j < 0:
            return ""
        return "".join(re.findall(r'"([^"]*)"', blocco[i:j]))

    i1 = corpo.find("if not gia:")
    i2 = corpo.find("if not gia:", i1 + 5)
    i0 = corpo.find('if a["origine_d"]:')
    sql_tit = sql_di(corpo[i1:i2]) if 0 <= i1 < i2 else ""
    sql_d = sql_di(corpo[i0:i1]) if 0 <= i0 < i1 else ""
    prova("si ritrova la query del match per titolo", True,
          "WHERE titolo=?" in sql_tit and "stato='attivo'" in sql_tit)
    prova("...e quella del match per `d`", True,
          "WHERE nostr_origine_d=?" in sql_d)

    # E la si fa GIRARE: una sentinella sulla forma direbbe che la
    # clausola c'e', mai che escluda la riga giusta e lasci passare le
    # altre tre.
    con_i = sqlite3.connect(":memory:")
    con_i.executescript("""
    CREATE TABLE annunci(id INTEGER PRIMARY KEY, titolo TEXT, stato TEXT,
      venditore_id INT, contatto_nostr TEXT, nostr_origine_d TEXT,
      nostr_origine_foto TEXT, foto TEXT, nostr_event_id TEXT);
    INSERT INTO annunci VALUES
      (208,'con testa','attivo',955,'','','','','ev208'),
      (300,'legacy importato','attivo',955,'npub1lui','','','',''),
      (301,'nativo nudo','attivo',955,'','','','',''),
      (302,'testa NULL','attivo',955,'','','','',NULL);
    """)

    def adotta(titolo):
        if not sql_tit:
            return "QUERY NON RITROVATA"
        r = con_i.execute(sql_tit,
                          (titolo, 955, "npub1lui", "d-suo")).fetchone()
        return r[0] if r else None

    prova("una riga NATIVA con la sua testa non si adotta", None,
          adotta("con testa"))
    prova("...ma l'importato di ieri senza testa si', come sempre",
          300, adotta("legacy importato"))
    prova("...e il nativo senza testa pure (non e' una riga a due teste)",
          301, adotta("nativo nudo"))
    prova("...e una testa a NULL non e' una testa", 302,
          adotta("testa NULL"))
    # La riga da non ammorbidire: guardare ANCHE il match per `d`
    # smetterebbe di ritrovare le righe gia' adottate, e l'import ne
    # creerebbe copie nuove.
    prova("il match per `d` NON porta la clausola", False,
          "nostr_event_id" in sql_d)

    # --- La cintura dall'altro lato: la firma che torna dal browser ---
    # Se la riga e' diventata importata mentre la firma era per strada,
    # scriverle una testa la farebbe «a due teste» dall'altra porta.
    # Qui l'endpoint si fa GIRARE per davvero, e le tre risposte sono
    # diverse: importata+pubblica non scrive, nativa scrive come
    # sempre, e la RITIRA azzera comunque — ritirare toglie una testa,
    # non ne mette una.
    class _Err(Exception):
        def __init__(self, codice, testo=""):
            self.codice, self.testo = codice, testo
            super().__init__(f"{codice}: {testo}")

    class _SenzaClose:
        def __init__(self, c): self._c = c
        def __getattr__(self, n): return getattr(self._c, n)
        def close(self): pass

    class _ChiaveFinta:
        def __init__(self, _b): pass
        def verify(self, *_a): return True

    CHIAVE = "bb" * 32
    EV_NUOVO = "ab" * 32

    def firma(azione, annuncio):
        """Il POST vero su un database di cartone. Torna (testa,
        autore, quante firme restano in coda per quell'annuncio)."""
        c = sqlite3.connect(":memory:")
        c.row_factory = sqlite3.Row
        c.executescript("""
        CREATE TABLE annunci(id INTEGER PRIMARY KEY, contatto_nostr TEXT,
          nostr_event_id TEXT, nostr_autore TEXT);
        CREATE TABLE utenti(tg_id INT, npub TEXT, npub_verificata INT,
          npub_accesso TEXT);
        CREATE TABLE firme_nostr(annuncio_id INTEGER PRIMARY KEY,
          tg_id INT, azione TEXT);
        INSERT INTO annunci VALUES(208,'npub1lui','',''),
                                  (209,'npub1lui','ev-vecchio','bb'),
                                  (301,'','','');
        INSERT INTO utenti VALUES(955,'','','');
        INSERT INTO firme_nostr VALUES(208,955,'x'),(209,955,'x'),
                                      (301,955,'x');
        """)

        async def json_finto(_req):
            return {"biglietto": "B", "pubkey": CHIAVE, "sig": "cd" * 64}

        amb = {"Request": object, "Header": lambda d: d,
               "Cookie": lambda d: d, "HTTPException": _Err,
               "verifica_utente": lambda *a: {"id": 955},
               "leggi_json": json_finto,
               "BIGLIETTI_FIRMA_NOSTR": {
                   "B": {"scade": 9e9, "tg_id": 955, "azione": azione,
                         "annuncio_id": annuncio, "kind": 30402,
                         "tags": [], "content": "", "created_at": 1}},
               "RE_HEX_64": re.compile("[0-9a-f]{64}"),
               "RE_HEX_128": re.compile("[0-9a-f]{128}"),
               "ChiavePubblicaNostr": _ChiaveFinta,
               "chiave_nostr_provata": lambda u: CHIAVE,
               "evento_non_firmato": lambda *a: {"id": EV_NUOVO},
               "db": lambda: _SenzaClose(c),
               "time": type("t", (), {"time": staticmethod(lambda: 1)})}
        exec("async " + pezzo("firma_nostr_fatta"), amb)
        asyncio.run(amb["firma_nostr_fatta"](None))
        r = c.execute("SELECT nostr_event_id, nostr_autore FROM annunci "
                      "WHERE id=?", (annuncio,)).fetchone()
        coda = c.execute("SELECT COUNT(*) FROM firme_nostr "
                         "WHERE annuncio_id=?", (annuncio,)).fetchone()[0]
        return r["nostr_event_id"], r["nostr_autore"], coda

    prova("sulla riga diventata importata non si scrive nessuna testa",
          ("", "", 0), firma("pubblica", 208))
    prova("...e su una gia' a due teste non se ne scrive una seconda",
          ("ev-vecchio", "bb", 0), firma("pubblica", 209))
    prova("la RITIRA azzera comunque (toglie una testa, non ne mette)",
          ("", "", 0), firma("ritira", 209))
    prova("sulla riga nativa si scrive come sempre",
          (EV_NUOVO, CHIAVE, 0), firma("pubblica", 301))

    # E la coda si svuota da sola, o il browser rifirma e ripubblica
    # sui relay a ogni apertura (svuotaFirmeNostr gira in avvia()).
    corpo_get = pezzo("firme_nostr_da_fare")
    k = corpo_get.find("azione<>'ritira'")
    inizio = corpo_get.rfind("con.execute(", 0, k) if k > 0 else -1
    fine = corpo_get.find("(user[", k) if k > 0 else -1
    sql_del = ("".join(re.findall(r'"([^"]*)"', corpo_get[inizio:fine]))
               if 0 <= inizio < fine else "")
    prova("si ritrova la pulizia di coda del GET", True,
          sql_del.startswith("DELETE FROM firme_nostr"))
    c2 = sqlite3.connect(":memory:")
    c2.executescript("""
    CREATE TABLE annunci(id INTEGER PRIMARY KEY, contatto_nostr TEXT);
    CREATE TABLE firme_nostr(annuncio_id INTEGER PRIMARY KEY, tg_id INT,
      azione TEXT);
    INSERT INTO annunci VALUES(208,'npub1lui'),(209,'npub1lui'),(301,'');
    INSERT INTO firme_nostr VALUES(208,955,'pubblica'),(209,955,'ritira'),
                                  (301,955,'pubblica');
    """)
    if sql_del:
        c2.execute(sql_del, (955,))
    prova("la coda perde la 'pubblica' su una riga importata, e tiene "
          "la 'ritira' e le righe native", [209, 301],
          [r[0] for r in c2.execute("SELECT annuncio_id FROM firme_nostr "
                                    "ORDER BY annuncio_id")])

    # --- IL RAMO «SOLD» (ago 2026) --------------------------------
    # Lo stesso match per titolo, e la stessa clausola: un evento suo
    # marcato `sold` non deve spegnere come «venduto» una riga NATIVA
    # omonima. Non e' cosmesi — al riavvio dopo, la riparazione
    # dell'invariante (`quantita=0 WHERE stato='venduto'`) le azzera
    # anche lo stock.
    i3 = corpo.find('if st and st[1] == "sold":')
    i4 = corpo.find("if not morto and tt:", i3) if i3 >= 0 else -1
    i5 = corpo.find("if morto:", i4) if i4 >= 0 else -1
    sql_sold = sql_di(corpo[i4:i5], "(tt[") if 0 <= i4 < i5 else ""
    sql_sold_d = (sql_di(corpo[i3:i4], "(dt[") if 0 <= i3 < i4 else "")
    prova("si ritrova la query per titolo del ramo sold", True,
          "WHERE titolo=?" in sql_sold and "stato='attivo'" in sql_sold)

    def spegne(titolo):
        if not sql_sold:
            return "QUERY NON RITROVATA"
        r = con_i.execute(sql_sold,
                          (titolo, 955, "npub1lui", "d-suo")).fetchone()
        return r[0] if r else None

    prova("un `sold` suo non spegne la riga NATIVA con la sua testa",
          None, spegne("con testa"))
    prova("...ma spegne ancora l'importato di ieri senza testa",
          300, spegne("legacy importato"))
    prova("...e il nativo senza testa, come sempre", 301,
          spegne("nativo nudo"))
    prova("anche qui il match per `d` resta senza clausola", False,
          "nostr_event_id" in sql_sold_d)

    # --- LA DEDUPLICA NELL'ERA DEL BIVIO --------------------------
    # Il ritiro di un doppione il cui evento e' firmato dall'UTENTE non
    # e' un fallimento: e' un'attesa. Si fa girare l'endpoint VERO,
    # con dentro il ritira_da_nostr VERO e il suo accoda_firma VERO —
    # cosi' la prova non dice «c'e' un ramo», dice «non alza il 502 e
    # la firma finisce in coda».
    corpo_rit = pezzo("ritira_doppione")

    def ritira(autore, relay_ok):
        c = sqlite3.connect(":memory:")
        c.row_factory = sqlite3.Row
        c.executescript("""
        CREATE TABLE annunci(id INTEGER PRIMARY KEY, venditore_id INT,
          contatto_nostr TEXT, nostr_event_id TEXT, nostr_autore TEXT);
        CREATE TABLE firme_nostr(annuncio_id INTEGER PRIMARY KEY,
          tg_id INT, azione TEXT, creato INT);
        """)
        c.execute("INSERT INTO annunci VALUES(7,955,'','ev7',?)", (autore,))
        spediti = []

        async def ai_relay(_ev):
            spediti.append(_ev)
            return relay_ok

        amb = {"Header": lambda d: d, "Cookie": lambda d: d,
               "HTTPException": _Err, "db": lambda: _SenzaClose(c),
               "verifica_utente": lambda *a: {"id": 955},
               "_NOSTR": (None, "aa" * 32),
               "firma_evento": lambda *a: {"id": "ev-morte"},
               "_spedisci_ai_relay": ai_relay,
               "RELAYS_VERIFICA": ["uno"],
               "time": type("t", (), {"time": staticmethod(lambda: 1)})}
        # accoda_firma nello STESSO ambiente e non con reale(): quello
        # esegue il pezzo in un env suo, dove `time` non c'e' — e il
        # try/except di ritira_da_nostr si mangerebbe il NameError
        # lasciando la coda vuota senza dire perche' (ci si e'
        # inciampati scrivendo questa prova: l'ha detto lei, non la
        # rilettura).
        exec(pezzo("accoda_firma"), amb)
        # ...e `_lapide_nostra` per la stessa ragione: da quando il
        # ritiro e il trasloco compongono la NIP-09 in un posto solo,
        # `ritira_da_nostr` la chiama — e senza, il suo try/except si
        # mangerebbe il NameError lasciando la coda vuota senza dire
        # perche'. E' la lezione di sempre: chi ESTRAE una funzione ne
        # eredita le dipendenze, e l'ambiente della prova va con lei.
        exec(pezzo("_lapide_nostra"), amb)
        exec("async " + pezzo("ritira_da_nostr"), amb)
        exec("async " + corpo_rit, amb)
        try:
            d = asyncio.run(amb["ritira_doppione"](7))
        except _Err as e:
            d = f"{e.codice}"
        coda = [r[0] for r in c.execute("SELECT azione FROM firme_nostr")]
        testa = c.execute("SELECT nostr_event_id FROM annunci "
                          "WHERE id=7").fetchone()[0]
        return d, coda, testa, len(spediti)

    d, coda, testa, spediti = ritira("bb" * 32, 0)
    prova("evento SUO: niente 502, si dice che la firma e' pronta",
          {"ok": True, "firma": True}, d)
    prova("...la richiesta di ritiro finisce in coda", ["ritira"], coda)
    prova("...e ai relay non si e' spedito niente", 0, spediti)
    prova("...e la testa resta finche' lui non firma", "ev7", testa)
    d, coda, testa, spediti = ritira("", 1)
    prova("evento NOSTRO coi relay che rispondono: ritirato",
          {"ok": True, "relay": 1}, d)
    prova("...e la testa se ne va", "", testa)
    prova("...senza chiedere nessuna firma", [], coda)
    d, _, testa, _ = ritira("", 0)
    prova("evento NOSTRO coi relay muti: 502, ed e' vero", "502", d)
    prova("...e non e' cambiato niente", "ev7", testa)

    # I testi del cassetto: la bugia di ieri non deve tornare, e il
    # flag deve viaggiare fin dentro il bottone.
    mini = open("miniapp.html", encoding="utf-8").read()
    prova("il cassetto non chiama piu' «di Barattolo» un evento suo",
          False, "pubblicato da Barattolo" in mini
                 or "Ritira il doppione di Barattolo" in mini)
    prova("l'etichetta del nativo si sceglie su chi ha firmato", True,
          "firmato da te" in mini and "firmato da noi" in mini)
    prova("...e il flag arriva dal server", True,
          '"firmato_da_te": bool(nat["nostr_autore"])' in _SORGENTE)
    prova("il cassetto dice anche cosa il bottone NON fa", True,
          "In vetrina restano comunque due" in mini)
    prova("e l'importato si riconosce in «I tuoi annunci»", True,
          "Importato dal tuo client Nostr" in mini)


# ====================================================================
def prove_categorie():
    """Il catalogo e' UNO: server, frontend e import devono dire le
    stesse categorie. Questa prova esiste perche' aggiungerne una
    vuol dire toccare SETTE posti, ed e' facile dimenticarne uno."""
    print("\n[categorie]")
    import re
    amb = {}
    i = _SORGENTE.index("CATEGORIE = (")
    exec(_SORGENTE[i:_SORGENTE.index(")", i) + 1], amb)
    cat = list(amb["CATEGORIE"])
    prova("«Altro» chiude sempre il catalogo", "Altro", cat[-1])
    prova("nessun doppione", len(cat), len(set(cat)))

    html = open("miniapp.html", encoding="utf-8").read()
    i = html.index("const CATS = [")
    front = re.findall(r'"([^"]+)"', html[i:html.index("]", i)])
    prova("le pillole del frontend combaciano col server",
          ["Tutto"] + cat, front)

    i = html.index('<select id="sellCat"')
    sel = re.findall(r"<option>([^<]+)</option>",
                     html[i:html.index("</select>", i)])
    prova("il form Vendi offre tutto il catalogo", cat, sel)

    i = html.index("const EMOJI_CAT = {")
    emoji = re.findall(r"'([^']+)':'", html[i:html.index("};", i)])
    prova("ogni categoria ha la sua emoji", sorted(cat), sorted(emoji))

    # Anche i dati finti della DEMO devono parlare il catalogo vero,
    # o le pillole non li aggancerebbero e la demo mostrerebbe una
    # vetrina vuota — che e' il posto peggiore per una figuraccia.
    demo = sorted(set(re.findall(r'cat:"([^"]+)"', html)))
    prova("le categorie della demo esistono nel catalogo",
          [], [c for c in demo if c not in cat])

    # L'import NON indovina piu' la categoria: gli annunci che
    # arrivano da Nostr nascono in «Altro» e a collocarli e' il
    # venditore. Questa prova esiste perche' l'indovinello e' una
    # tentazione che torna: sbaglia in silenzio, e sugli importati
    # nessuno se ne accorge.
    import importa_nostr as imp
    prova("l'import non indovina piu' le categorie", False,
          hasattr(imp, "categoria_automatica"))

    exec(pezzo("categoria_tollerante"), amb)
    i = _SORGENTE.index("SINONIMI_CATEGORIA = {")
    exec(_SORGENTE[i:_SORGENTE.index("\n}", i) + 2], amb)
    orfani = sorted({v for v in amb["SINONIMI_CATEGORIA"].values()
                     if v not in cat})
    prova("nessun sinonimo punta a una categoria che non esiste",
          [], orfani)
    prova("il CSV che dice «bevande» viene capito", "Alimenti e bevande",
          amb["categoria_tollerante"]("bevande"))
    prova("e chi scrive «profumi» finisce nella bellezza",
          "Bellezza e benessere", amb["categoria_tollerante"]("profumi"))

    # Il SESTO posto, che il cantiere aveva dimenticato: il modello CSV
    # che scaricano i commercianti. Non rompe niente se resta indietro
    # (categoria_tollerante ripiega sulla prima parola), ma insegna
    # nomi che non esistono — ed e' il primo file che un negozio nuovo
    # apre. La colonna della categoria e' la quinta.
    i = _SORGENTE.index("MODELLO_IMPORT = (")
    exec(_SORGENTE[i:_SORGENTE.index("\n\n", i)], amb)
    righe = [r for r in amb["MODELLO_IMPORT"].strip().splitlines() if r]
    del righe[0]                                   # l'intestazione
    prova("le categorie del modello CSV esistono nel catalogo", [],
          [r.split(";")[4] for r in righe if r.split(";")[4] not in cat])
    prova("una categoria inventata finisce in Altro", "Altro",
          amb["categoria_tollerante"]("fantacategoria"))
    for c in cat:
        if amb["categoria_tollerante"](c) != c:
            prova(f"il catalogo passa da categoria_tollerante ({c})",
                  c, amb["categoria_tollerante"](c))

    # Il SETTIMO posto (lug 2026, pagina Sfoglia): l'illustrazione. E'
    # anche l'unico che non si vede finche' non si apre la pagina — una
    # piastrella senza immagine mostra l'emoji di ripiego e sembra
    # quasi giusta. Meglio che a dirlo sia la CI.
    exec(pezzo("slug_categoria"), amb)
    slug = amb["slug_categoria"]

    # ============ LE DUE VOCI DELLE PRESTAZIONI (ago 2026) ============
    prova("le due categorie delle prestazioni ci sono", True,
          "Lezioni e corsi" in cat and "Lavoro e servizi" in cat)
    prova("...in coda, prima di «Altro»",
          ["Lezioni e corsi", "Lavoro e servizi", "Altro"], list(cat[-3:]))
    # LE EMOJI RISPECCHIANO L'ILLUSTRAZIONE, ed e' il loro mestiere: il
    # ripiego di un disegno, e nella griglia del bot l'unica cosa che
    # si vede. Il tocco col diploma e la valigetta SONO quei due file.
    i = html.index("const EMOJI_CAT = {")
    emo = dict(re.findall(r"'([^']+)':'([^']+)'", html[i:html.index("};", i)]))
    prova("il tocco al reparto delle lezioni", "🎓", emo["Lezioni e corsi"])
    prova("la valigetta a quello dei servizi", "💼", emo["Lavoro e servizi"])

    # --- L'ICONA DELLA STRADA NON E' PIU' QUELLA DEL REPARTO. Fino a
    # ieri 🎓 era la strada «servizio»; adesso e' il reparto, e la
    # strada ha 📅, che e' gia' l'icona del suo stesso flusso — ci si
    # accorda su una data. Nessuna prova sorvegliava quel glifo: e' il
    # censimento che mancava, e vieta al 🎓 di tornare a dire due cose.
    # ⚠️ si guarda il CODICE e non la prosa: nel client i commenti
    # sono a BLOCCO e le righe di mezzo non cominciano per «*»,
    # quindi un filtro riga-per-riga inciampa nella spiegazione che
    # racconta lo scambio. Chi la scrive non deve riscrivere la
    # frase: e' la sentinella a dover guardare dove serve.
    codice_js = re.sub(r"/\*.*?\*/", "", html, flags=re.S)
    prova("il 🎓 nel client e' SOLO il reparto, mai la strada", [],
          [r.strip()[:56] for r in codice_js.split("\n")
           if "🎓" in r and "Lezioni e corsi" not in r])
    prova("...e nel server idem", [],
          [r.strip()[:56] for r in _SORGENTE.split("\n")
           if "🎓" in r and "Lezioni e corsi" not in r
           and not r.strip().startswith("#")])
    prova("la strada porta il 📅 dove si sceglie e dove si racconta",
          True, all("📅" in html[html.index(d) - 240:html.index(d) + 240]
                    for d in ("v==='servizio' ?", 'id="notaServizio"')))

    # --- LA NOTA NASCE APERTA anche sulle lezioni: li' la domanda e'
    # certa quanto su una taglia. ⚠️ Questo elenco era l'UNICO del
    # catalogo che nessuna prova incrociava: un refuso ci passava.
    i = html.index("const CAT_NOTA_APERTA = [")
    apre = re.findall(r"'([^']+)'", html[i:html.index("]", i)])
    prova("le categorie della nota aperta esistono nel catalogo", [],
          [c for c in apre if c not in cat])
    prova("...e le lezioni ci sono", True, "Lezioni e corsi" in apre)
    prova("...i servizi NO: una consulenza si concorda nell'annuncio",
          False, "Lavoro e servizi" in apre)

    # --- LE TRE SUPERFICI DELLA PRESTAZIONE, i buchi di ieri: la card
    # aveva la riga delle icone VUOTA su un servizio, e i due campi che
    # dicono DOVE e QUANTO DURA non uscivano da CAMPI_VETRINA — il
    # venditore li dichiarava e chi compra non li vedeva mai.
    cv = _SORGENTE[_SORGENTE.index("CAMPI_VETRINA = ("):]
    cv = cv[:cv.index("\n)")]
    prova("il dove e il quanto della prestazione escono in vetrina", True,
          "a.servizio_dove" in cv and "a.durata_min" in cv)
    ico = pezzo_js(html, "function iconeCard(l){")
    prova("la card dice la strada anche su una prestazione", True,
          "l.consegna === 'servizio'" in ico and "📅" in ico)
    prova("...e distingue l'online dal di persona", True, "presenza" in ico)
    pil = pezzo_js(html, "function pilloleModalita(l){")
    prova("la scheda ha la pillola della prestazione", True,
          "l.consegna==='servizio'" in pil and "📅" in pil)
    prova("...e ci mette la durata", True, "durataTesto(l.durataMin)" in pil)
    prova("la durata si dice in un posto solo", 1,
          html.count("function durataTesto("))

    prova("nessuno slug di categoria si sovrappone a un altro",
          len(cat), len({slug(c) for c in cat}))
    prova("il frontend calcola lo slug come il server", True,
          "c.toLowerCase().replace(/ /g,'-')" in html)
    prova("ogni categoria ha la sua illustrazione", [],
          [c for c in cat
           if not os.path.exists(f"assets/categorie/{slug(c)}.webp")])
    # e il suo francobollo per il foglio-picker di Vendi: si dimentica
    # facilmente, perche' manca solo la' dentro e il ripiego a emoji
    # fa sembrare che vada tutto bene
    prova("ogni categoria ha il suo francobollo -mini", [],
          [c for c in cat
           if not os.path.exists(f"assets/categorie/{slug(c)}-mini.webp")])

    # L'illustrazione della card «Tutto» in testa alla striscia (ago
    # 2026): «Tutto» non e' una categoria, quindi non sta in
    # SLUG_CATEGORIE — la rotta la ammette da una whitelist allargata
    # di UNA voce dichiarata a mano, e /categoria/tutto resta un nome
    # inventato, fuori dal vocabolario delle pagine reparto.
    prova("la rotta delle illustrazioni ammette anche «tutto»", True,
          'SLUG_ILLUSTRAZIONI = SLUG_CATEGORIE | {"tutto"}' in _SORGENTE
          and "base not in SLUG_ILLUSTRAZIONI" in _SORGENTE)
    # ...e il file c'e' davvero, col suo francobollo: senza, la card
    # in testa mostrerebbe per sempre l'emoji di ripiego e sembrerebbe
    # quasi giusta — la stessa ragione delle due prove qui sopra.
    prova("l'illustrazione di «Tutto» esiste", True,
          os.path.exists("assets/categorie/tutto.webp"))
    prova("...col suo francobollo -mini", True,
          os.path.exists("assets/categorie/tutto-mini.webp"))

    # Le illustrazioni devono essere TIRATE, cioe' senza margine
    # trasparente attorno (ci pensa ritaglia_categorie.py). Non e' una
    # pignoleria: la piastrella le posa in un riquadro tarato al pixel
    # sotto il nome, e un file con margini renderebbe il disegno
    # piccolo dentro quel riquadro — la cosa che si e' appena
    # sistemata. Peggio: il margine sposta il disegno verso l'alto e
    # le sue zone quasi bianche possono tornare sotto le lettere, dove
    # il nome in crema fa 1,00:1 e sparisce. Un testo invisibile non
    # lo nota nessuno finche' non lo segnala un utente: meglio la CI.
    try:
        from PIL import Image
    except ImportError:
        salta("il pareggio dell'inchiostro delle illustrazioni",
              "Pillow non e' installata")
    else:
        # Le illustrazioni devono essere PAREGGIATE, cioe' nessuna deve
        # coprire molto piu' inchiostro delle altre una volta resa in
        # piastrella (ci pensa ritaglia_categorie.py). Si misura
        # l'inchiostro e non il rettangolo perche' e' quello che
        # l'occhio pesa: un pallone e una chitarra possono avere lo
        # stesso rettangolo, ma il pallone e' pieno e sembra il triplo.
        # Il tetto e' generoso apposta — qui non si insegue la
        # perfezione, si prende il file rifatto che sfonda.
        BOX_W, BOX_H, TETTO = 85.9, 69.0, 1.30
        resi = {}
        for c in cat:
            p = f"assets/categorie/{slug(c)}.webp"
            if not os.path.exists(p):
                continue
            # il file si misura COM'E', bordo trasparente compreso: e'
            # quello che scala il browser, ed e' proprio quel bordo a
            # fare il pareggio. Ritagliarlo qui vorrebbe dire annullare
            # la cosa che si sta verificando (successo per davvero).
            a = Image.open(p).convert("RGBA").getchannel("A")
            ink = sum(n * i for i, n in enumerate(a.histogram())) / 255.0
            s = min(BOX_W / a.size[0], BOX_H / a.size[1])
            resi[c] = ink * s * s
        if resi:
            ordinati = sorted(resi.values())
            mediana = ordinati[len(ordinati) // 2]
            prova("nessuna illustrazione pesa piu' delle altre in griglia",
                  [], [c for c, v in resi.items() if v > mediana * TETTO])


