    prova("fai_offerta: il titolo nasce scappato", True,
          "titolo = html.escape(" in fai)
    prova("fai_offerta: la notifica dice le due facce", True,
          "_cifra_accordo(" in fai)
    # la migrazione c'e' (la PRIMA su `offerte`) e NON inventa un
