    prova("cifraAccordo passa i pezzi al gemello", True,
          "cifraPezzi(o.valuta, a.sats, a.eur, o.quantita||0)" in mini)
    # LA QUANTITA' E' UNA SOLA VARIABILE, e non una copia: il foglio ha
