    prova("setQta riscrive l'etichetta, non solo una cifra", True,
          "q('.tasto-offerta').forEach(b => b.innerHTML = "
          "etichettaOfferta(l));" in mini)
    # con l'accordo la quantita' non si sceglie piu': lo stepper
